import {Run,LEVELS,RIDERS,COURSE_LIMIT,clamp,sectionAt,sectionNames} from './engine.mjs';
import {createProfile,SAVE_KEY,purchaseRider,settleRun,unlocked as isUnlocked} from './profile.mjs';
import {AlpineRenderer} from './scene.mjs';
export function boot(Renderer=AlpineRenderer){
 const $=id=>document.getElementById(id),canvas=$('world'),fmt=n=>Math.floor(n).toLocaleString('en-US'),clock=t=>Math.floor(t/60).toString().padStart(2,'0')+':'+Math.floor(t%60).toString().padStart(2,'0');
 const read=k=>{try{return JSON.parse(localStorage.getItem(k)||'null');}catch{return null;}};
 let state=createProfile(read(SAVE_KEY),read('driftbound.progress.v2')),muted=true,quality=(innerWidth<700||globalThis.matchMedia?.('(pointer: coarse)').matches)?'low':'high';try{muted=localStorage.getItem('driftbound.sound')!=='on';const savedQuality=localStorage.getItem('driftbound.quality');if(['low','high'].includes(savedQuality))quality=savedQuality;}catch{}
 const unlocked=i=>isUnlocked(state,i);let previewRider=state.rider;
 let mode='loading',run=new Run(state.level,undefined,state.claimed),renderer,keys=new Set(),pointer=null,last=0,time=0,hudClock=0,toastTime=0,finishTimer=0,helpReturn='home',pauseReturn='playing',keyboardPull=false,portrait=innerHeight>innerWidth,sceneMode='home',audio=null,windGain=null,coinSound=0;
 const save=()=>{try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));}catch{}};
 function bank(){const result=settleRun(state,run);save();return result;}
 function wallet(){const unbanked=run.active&&!run.settled;$('walletCoins').textContent=fmt(state.coins+(unbanked?run.coins:0));$('walletGems').textContent=fmt(state.diamonds+(unbanked?run.diamonds:0));}
 function soundUI(){$('pauseSound').textContent='Sound · '+(muted?'off':'on');$('soundMark').setAttribute('d',muted?'m16 9 6 6m0-6-6 6':'M16 8q5 4 0 8m3-11q8 7 0 14');$('sound').setAttribute('aria-label',muted?'Turn sound on':'Turn sound off');$('sound').title=muted?'Sound off':'Sound on';}
 function initAudio(){if(audio){audio.resume().catch(()=>{});return;}try{audio=new (window.AudioContext||window.webkitAudioContext)();const buffer=audio.createBuffer(1,audio.sampleRate*2,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.35;const noise=audio.createBufferSource();noise.buffer=buffer;noise.loop=true;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=430;windGain=audio.createGain();windGain.gain.value=0;noise.connect(filter).connect(windGain).connect(audio.destination);noise.start();}catch{muted=true;soundUI();}}
 function tone(freq=440,duration=.15,type='sine',volume=.05){if(muted||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.6,audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
 function cancelInput(){const old=pointer;pointer=null;keyboardPull=false;keys.clear();run.cancelLaunch();$('thumbPad').hidden=true;if(old){try{canvas.releasePointerCapture(old.id);}catch{}}}
 function setMode(next){cancelInput();mode=next;document.body.dataset.mode=next;$('home').hidden=next!=='home';$('trailBadge').hidden=next!=='home';$('footer').hidden=!['home','levels','riders'].includes(next);$('levelPicker').hidden=next!=='levels';$('riderPicker').hidden=next!=='riders';$('veil').hidden=!['home','levels','riders'].includes(next);
 const riding=['playing','paused','crashed','finishing'].includes(next)&&run.status!=='aiming';for(const id of ['hud','boostHud','rideDial'])$(id).hidden=!riding;
 $('launchHud').hidden=next!=='aiming';$('overlay').hidden=!['paused','result','help','error'].includes(next);$('result').hidden=next!=='result';$('pause').hidden=next!=='paused';$('help').hidden=next!=='help';$('errorDialog').hidden=next!=='error';$('loading').hidden=next!=='loading';$('powerHud').hidden=!(riding&&['playing','paused'].includes(next));
 if(next==='home'&&renderer){previewRider=state.rider;renderer.setRider(state.rider);}if(next!=='playing'){$('playHint').hidden=true;$('combo').hidden=true;$('spinButton').hidden=true;$('toast').classList.remove('show');document.body.classList.remove('boosting');}if(['home','levels','riders','playing','aiming'].includes(next))sceneMode=next;if(next==='aiming')updateLaunch();}
 function stars(n){return '★'.repeat(n)+'☆'.repeat(3-n);}
 function menus(){const l=LEVELS[state.level],r=RIDERS[state.rider],preview=RIDERS[previewRider],owned=state.owned.includes(preview.id);wallet();$('homeLevelTag').textContent='EXPEDITION '+String(state.level+1).padStart(2,'0')+' / 09';$('homeLevelName').textContent=l.name;$('homeLevelMeta').textContent=l.length+' m · '+l.tag;$('riderName').textContent=r.name;$('riderDot').style.background='#'+r.jacket.toString(16);$('badgeNumber').textContent=String(state.level+1).padStart(2,'0');$('badgeName').textContent=l.name;$('badgeTag').textContent=l.tag;$('badgeDesc').textContent=l.description;$('completedCount').textContent=Object.keys(state.completed).length+' / 9 EXPEDITIONS COMPLETE';
 $('levelCards').innerHTML=LEVELS.map((l,i)=>{const done=state.completed[i];return `<button class="level-card ${state.level===i?'selected':''}" data-level="${i}" ${unlocked(i)?'':'disabled'} aria-pressed="${state.level===i}"><span class="level-num">${String(i+1).padStart(2,'0')}</span><span class="level-detail"><strong>${l.name}</strong><small>${l.length} m · ${unlocked(i)?l.description:'Finish '+LEVELS[i-1].name+' to unlock.'}</small><small>${done?'BEST '+fmt(done.score)+' PTS · '+clock(done.time):'FIRST CLEAR: '+(80+i*15)+' COINS + 2 DIAMONDS'}</small></span><span class="level-mark">${done?stars(done.medals):unlocked(i)?'↗':'⌑'}</span></button>`;}).join('');
 $('riderCards').innerHTML=RIDERS.map((r,i)=>{const own=state.owned.includes(r.id);return `<button class="rider-card ${previewRider===i?'previewing':''} ${own?'':'locked'}" data-rider="${i}" aria-pressed="${previewRider===i}"><span class="rider-color" style="background:#${r.jacket.toString(16)}"></span><span><strong>${r.name}</strong><small>${r.role}</small><span class="price">${own?(state.rider===i?'EQUIPPED':'OWNED'):r.coins+' ●'+(r.diamonds?' + '+r.diamonds+' ◆':'')}</span></span><b>${state.rider===i?'✓':''}</b></button>`;}).join('');
 $('shopName').textContent=preview.name+' · '+preview.role;$('shopDescription').textContent=preview.description;$('shopStatus').textContent=owned?'Owned · same handling, unique look':preview.coins+' coins'+(preview.diamonds?' + '+preview.diamonds+' rare diamonds':'');$('confirmRider').innerHTML=(owned?'RIDE WITH '+preview.name.toUpperCase():'UNLOCK '+preview.name.toUpperCase())+' <span>↗</span>';
 }

 function loadLevel(index){if(!unlocked(index))return;bank();state.level=index;run=new Run(index,undefined,state.claimed);renderer.load(index,run,state.rider);menus();save();}
 function updateLaunch(){const p=run.launchPower||0;$('launchPercent').textContent=Math.round(p*100)+'%';$('launchFill').style.width=p*100+'%';$('launchHud').dataset.pulled=p>.05?'yes':'no';$('launchCaption').textContent=p>=.98?'FULL POWER · RELEASE':p>=.12?'RELEASE TO LAUNCH':'PULL DOWN TO LAUNCH';$('launchTrack').textContent=LEVELS[state.level].name+' · '+LEVELS[state.level].length+' m';$('launchMeter').setAttribute('aria-valuenow',Math.round(p*100));}
 function start(){clearTimeout(finishTimer);bank();run=new Run(state.level,undefined,state.claimed);run.prepareLaunch();renderer.load(state.level,run,state.rider);setMode('aiming');toastTime=0;time=0;last=performance.now();wallet();if(!muted)initAudio();}
 function releaseLaunch(){const power=run.launchPower||0;if(!run.launch()){run.cancelLaunch();updateLaunch();return false;}setMode('playing');last=performance.now();$('playHint').hidden=false;tone(260+power*430,.32,'triangle');toast(power>.92?'FULL SEND.':'LET IT FLY.',Math.round(power*100)+'% LAUNCH POWER');updateHUD();return true;}
 function home(){clearTimeout(finishTimer);bank();run=new Run(state.level,undefined,state.claimed);renderer.load(state.level,run,state.rider);setMode('home');menus();}
 function pause(){if(['playing','aiming'].includes(mode)){pauseReturn=mode;setMode('paused');$('resume').innerHTML=(pauseReturn==='aiming'?'BACK TO LAUNCH':'KEEP RIDING')+' <span>↗</span>';$('resume').focus();}}
 function resume(){if(mode==='paused'){setMode(pauseReturn);last=performance.now();}}
 function showHelp(){if(mode==='error'||mode==='loading')return;if(['playing','aiming'].includes(mode))pause();helpReturn=mode;setMode('help');$('closeHelp').focus();}
 function toast(text,sub){$('toast').innerHTML=text+'<small>'+sub+'</small>';$('toast').classList.add('show');toastTime=1.4;}
 function endRun(finished){setMode(finished?'finishing':'crashed');const loot=bank();tone(finished?880:90,finished?.5:.3,finished?'sine':'triangle',.10);
 finishTimer=setTimeout(()=>{$('resultEyebrow').textContent=finished?'EXPEDITION '+String(state.level+1).padStart(2,'0')+' COMPLETE':'THE MOUNTAIN IS CALLING';$('resultTitle').textContent=finished?(state.level===LEVELS.length-1?'Crown conquered.':'You made it.'):'Another line awaits.';$('medals').hidden=!finished;$('medals').innerHTML=[0,1,2].map(i=>`<span class="${i<run.medals?'':'empty'}">★</span>`).join('');$('medals').setAttribute('aria-label',run.medals+' of 3 medals');$('finalDistance').textContent=fmt(run.distance);$('finalDistanceLabel').textContent=finished?'METRES CONQUERED':'OF '+run.level.length+' METRES';$('finalScore').textContent=fmt(run.score);$('finalNear').textContent=run.nearMisses;$('finalTime').textContent=clock(run.time);$('runRewards').innerHTML='<span>+'+loot.coins+' COINS</span><span>+'+loot.diamonds+' DIAMONDS</span>';$('resultTip').textContent=finished?(state.level<LEVELS.length-1?LEVELS[state.level+1].name+' unlocked. '+(loot.first?'First-clear bonus banked.':'Your loot is banked.'):'Nine mountains conquered. Chase every medal and rare diamond.'):'Collected loot is banked. Find a new line and go again.';$('nextLevel').hidden=!finished;$('nextLevel').innerHTML=(state.level===LEVELS.length-1?'VIEW EXPEDITIONS':'NEXT EXPEDITION')+' <span>↗</span>';$('restart').innerHTML=(finished?'RIDE THIS ROUTE AGAIN':'TRY AGAIN')+' <span>↗</span>';wallet();setMode('result');(finished?$('nextLevel'):$('restart')).focus();},finished?800:500);}

 function updateHUD(){const l=run.level;wallet();$('scoreGoal').textContent='SCORE / '+fmt(l.goal);$('sectionLabel').textContent=sectionNames[sectionAt(l,run.distance).type];$('spinButton').hidden=mode!=='playing'||!run.air||run.airHeight<1.4||run.vy<=-5||!!run.trick;const chips=[];for(const [k,label]of [['magnet','MAGNET'],['shield','SHIELD'],['double','2× COINS']])if(run[k]>0)chips.push('<span class="power-chip">'+label+' '+run[k].toFixed(1)+'s</span>');if(run.air)chips.push('<span class="power-chip air">AIR '+run.airTime.toFixed(1)+'s · '+run.airHeight.toFixed(1)+'m</span>');$('powerHud').innerHTML=chips.join('');$('levelHud').textContent='0'+(state.level+1)+' · '+l.name.toUpperCase();$('distance').innerHTML=fmt(Math.max(0,l.length-Math.max(0,run.distance)))+'<small> m to finish</small>';$('score').textContent=fmt(run.score);$('speed').textContent=Math.round(run.speed*3.6)+' km/h';$('dialSpeed').textContent=Math.round(run.speed*3.6);$('speedArc').setAttribute('stroke-dashoffset',238.8*(1-clamp(run.speed*3.6/140,0,1)));$('time').textContent=clock(run.time);$('routeFill').style.width=run.progress*100+'%';const active=run.boost>0,p=active?run.boost/3.2*100:run.charge;$('boostFill').style.width=p+'%';$('boostPercent').textContent=active?run.boost.toFixed(1)+'s':Math.floor(p)+'%';$('boostLabel').textContent=active?'⚡ BOOST ACTIVE — HOLD YOUR LINE':'⚡ CLOSE CALLS CHARGE BOOST';document.body.classList.toggle('boosting',active);$('combo').hidden=run.combo<2||mode!=='playing';$('combo').querySelector('strong').textContent=run.combo+'×';$('playHint').hidden=run.time>5||mode!=='playing';}
 function spin(){if(mode==='playing'&&run.spin()){toast('MAKE IT A 360.','STICK THE LANDING');tone(720,.18);}}$('spinButton').onclick=spin;$('quickLaunch').onclick=()=>{if(mode==='aiming'){run.pullLaunch(.75);releaseLaunch();}};$('launchBack').onclick=home;
 $('start').onclick=start;$('restart').onclick=start;$('retryPause').onclick=start;$('resume').onclick=resume;$('pauseButton').onclick=()=>mode==='paused'?resume():pause();$('backHome').onclick=home;$('quit').onclick=home;$('helpButton').onclick=showHelp;$('footerHelp').onclick=showHelp;$('closeHelp').onclick=()=>setMode(helpReturn);$('reload').onclick=()=>location.reload();
 $('chooseLevel').onclick=()=>{menus();setMode('levels');};$('chooseRider').onclick=()=>{previewRider=state.rider;$('shopMessage').textContent='';menus();setMode('riders');};$('levelsBack').onclick=()=>setMode('home');$('ridersBack').onclick=()=>setMode('home');$('confirmRider').onclick=()=>{const result=purchaseRider(state,previewRider);if(!result.ok){const r=RIDERS[previewRider];$('shopMessage').textContent='Still needed: '+Math.max(0,r.coins-state.coins)+' coins and '+Math.max(0,r.diamonds-state.diamonds)+' diamonds.';return;}save();renderer.setRider(state.rider);menus();setMode('home');};
 $('levelCards').onclick=e=>{const el=e.target.closest('[data-level]');if(!el)return;const i=Number(el.dataset.level);if(!unlocked(i))return;loadLevel(i);};$('riderCards').onclick=e=>{const el=e.target.closest('[data-rider]');if(!el)return;const i=Number(el.dataset.rider);if(!RIDERS[i])return;previewRider=i;$('shopMessage').textContent='';renderer.setRider(i);menus();};
 $('nextLevel').onclick=()=>{if(state.level<LEVELS.length-1){state.level++;save();start();}else{home();setMode('levels');}};
 document.querySelector('.brand').onclick=e=>{e.preventDefault();if(['playing','aiming'].includes(mode))pause();else if(mode!=='error'&&mode!=='loading')home();};
 $('sound').onclick=()=>{muted=!muted;if(!muted)initAudio();soundUI();try{localStorage.setItem('driftbound.sound',muted?'off':'on');}catch{}};
 $('pauseSound').onclick=()=>$('sound').onclick();$('pauseQuality').onclick=()=>$('quality').onclick();$('quality').onclick=()=>{if(!renderer)return;quality=quality==='high'?'low':'high';renderer.setQuality(quality);$('quality').textContent='3D · '+(quality==='high'?'HIGH':'PERF');$('pauseQuality').textContent='Graphics · '+(quality==='high'?'high':'performance');$('quality').setAttribute('aria-label',quality==='high'?'Switch to performance graphics':'Switch to high graphics');try{localStorage.setItem('driftbound.quality',quality);}catch{}};
 addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','ArrowUp','ArrowDown'].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.repeat)return;
 if(e.key==='Escape'||e.key.toLowerCase()==='p'){if(['playing','aiming'].includes(mode))pause();else if(mode==='paused')resume();else if(mode==='help')setMode(helpReturn);else if(['riders','levels'].includes(mode))setMode('home');}
 if(e.key.toLowerCase()==='r'&&mode==='result')start();if(e.key===' '){if(mode==='home')start();else if(mode==='aiming'&&!pointer)keyboardPull=true;else if(mode==='playing')spin();}});
 addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());if(e.key===' '&&keyboardPull&&mode==='aiming'){keyboardPull=false;releaseLaunch();}});
 addEventListener('blur',()=>{cancelInput();pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelInput();pause();}});
 addEventListener('resize',()=>{renderer?.resize();const nextPortrait=innerHeight>innerWidth;if(nextPortrait!==portrait){portrait=nextPortrait;cancelInput();pause();}});
 const drawThumb=(dx=0,dy=0)=>{$('thumbKnob').style.transform='translate('+clamp(dx,-32,32)+'px,'+clamp(dy,-22,22)+'px)';};
 canvas.addEventListener('pointerdown',e=>{if(!['playing','aiming'].includes(mode)||pointer||keyboardPull||e.isPrimary===false||(e.pointerType==='mouse'&&e.button!==0))return;pointer={id:e.pointerId,x:e.clientX,y:e.clientY,target:run.target};try{canvas.setPointerCapture(e.pointerId);}catch{}if(mode==='playing'&&e.pointerType!=='mouse'){$('thumbPad').hidden=false;$('thumbPad').style.left=clamp(e.clientX,48,innerWidth-48)+'px';$('thumbPad').style.top=clamp(e.clientY,48,innerHeight-48)+'px';drawThumb();}});
 canvas.addEventListener('pointermove',e=>{if(pointer?.id!==e.pointerId)return;if(mode==='aiming'){run.pullLaunch((e.clientY-pointer.y)/clamp(innerHeight*.22,90,180));updateLaunch();}else if(mode==='playing'){run.target=clamp(pointer.target+(e.clientX-pointer.x)*16.4/clamp(innerWidth*.65,190,320),-COURSE_LIMIT,COURSE_LIMIT);drawThumb(e.clientX-pointer.x,e.clientY-pointer.y);}});
 const release=(e,cancel=false)=>{if(pointer?.id!==e.pointerId)return;pointer=null;$('thumbPad').hidden=true;if(mode==='aiming'){if(cancel){run.cancelLaunch();updateLaunch();}else releaseLaunch();}try{canvas.releasePointerCapture(e.pointerId);}catch{}};
 canvas.addEventListener('pointerup',e=>release(e));canvas.addEventListener('pointercancel',e=>release(e,true));canvas.addEventListener('lostpointercapture',e=>release(e,true));
 canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();pause();$('errorText').textContent='The graphics connection was interrupted. Reload to restore the scene. Your completed levels are saved.';setMode('error');});
 function frame(now){if(mode==='error')return;const dt=Math.min(Math.max(0,(now-(last||now))/1000),.10);last=now;if(mode==='playing'){time+=dt;const steer=(keys.has('arrowright')||keys.has('d')?1:0)-(keys.has('arrowleft')||keys.has('a')?1:0);run.step(dt,steer);for(const event of run.events){if(event.type==='coin'){if(time-coinSound>.08){tone(1000,.065,'sine',.025);coinSound=time;}}else if(event.type==='diamond'){toast('RARE FIND.','+1 DIAMOND');tone(1400,.3);}else if(event.type==='power'){const labels={magnet:'COIN MAGNET',shield:'SHIELD READY',nitro:'NITRO RUSH',double:'DOUBLE COINS'};toast(labels[event.value],'POWER-UP COLLECTED');tone(760,.25);}else if(event.type==='save'){toast('SHIELD SAVE!','KEEP YOUR LINE');tone(340,.3);}else if(event.type==='trick'){toast('360 LANDED.','+250 POINTS · +5 COINS');tone(1000,.2);}else if(event.type==='section'){toast(sectionNames[event.value],'FIND YOUR NEXT LINE');}else if(event.type==='near'){toast('CLOSE CALL!','+'+100*event.value+' POINTS · '+event.value+'× CHAIN');tone(700+event.value*100,.13);}else if(event.type==='boost'){toast('LET IT RIP.','BOOST ACTIVATED');tone(350,.35,'triangle');}else if(event.type==='jump'){toast('SEND IT.','TAP SPIN / SPACE IN THE AIR');tone(550,.18);}else if(event.type==='crash')endRun(false);else if(event.type==='finish')endRun(true);}toastTime-=dt;if(toastTime<=0)$('toast').classList.remove('show');hudClock+=dt;if(hudClock>.08||!run.alive){updateHUD();hudClock=0;}}else if(['home','levels','riders','aiming'].includes(mode)){time+=dt;if(mode==='aiming'&&keyboardPull){run.pullLaunch((run.launchPower||0)+dt*.78);updateLaunch();}}
 if(windGain&&audio)windGain.gain.setTargetAtTime(!muted&&mode==='playing'?.04+run.speed*.002:0,audio.currentTime,.1);renderer.render(run,['playing','home','levels','riders','aiming'].includes(mode)?dt:0,['paused','result','help','crashed','finishing'].includes(mode)?sceneMode:mode,time);requestAnimationFrame(frame);}
 soundUI();menus();try{renderer=new Renderer(canvas);renderer.setQuality(quality);renderer.load(state.level,run,state.rider);$('quality').textContent='3D · '+(quality==='high'?'HIGH':'PERF');$('pauseQuality').textContent='Graphics · '+(quality==='high'?'high':'performance');setMode('home');requestAnimationFrame(frame);}catch(error){console.error('Driftbound graphics startup:',error);$('errorText').textContent='The 3D scene could not start. Try an updated browser with WebGL 2 and graphics acceleration enabled.';setMode('error');}
 return {get run(){return run;},get mode(){return mode;},get progress(){return state;},start,home,pause,resume,loadLevel,renderer};
}
if(!globalThis.__DRIFTBOUND_TEST__)boot();
